-- public.aqueduct_says(p_world uuid, b bridge)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.aqueduct_says(p_world uuid, b bridge)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_chain jsonb; v_st jsonb; v_into jsonb; v_foot text;
begin
  select s.chain, st into v_chain, v_st from spring s, jsonb_array_elements(s.chain->'streams') st
   where s.world_id = p_world and st ? 'via' and (st->>'via')::bigint = b.id
   order by s.id limit 1;
  if v_st is null then
    return 'Last span laid. Channel dry: no spring water at its head at ' || metres(b.height) || ' m'
      || ' or over.';
  end if;
  v_into := case when jsonb_typeof(v_st->'to') = 'number' then v_chain->'ponds'->((v_st->>'to')::int) end;
  v_foot := case
    when coalesce((v_st->>'fountain')::boolean, false) then 'Keeps the fountain at its foot full.'
    when exists (select 1 from foundation f where f.world_id = p_world and f.x = b.bx and f.y = b."by" and bill_done(f.needed) and not f.pool)
      then 'Pours onto the foundation; runs off its lowest edge.'
    when v_into ? 'tiles' and v_into ? 'spill' then 'Pool at its foot full; spills over its lowest edge.'
    when v_into ? 'tiles' then 'Pool at its foot full; nothing lower beside it, so it holds.'
    -- Standing at its level already: another spring's pond, or this one's own water there before.
    when v_into ? 'volume' and (v_into->>'from')::int >= (v_into->>'level')::int
      then 'Pond at its foot full; spills over its lip.'
    when v_into ? 'volume' then 'Fills the hollow to ' || metres((v_into->>'level')::int) || ' m in '
      || fill_words((v_into->>'volume')::double precision / aqueduct_lps()) || ', then spills over its lip.'
    else 'Pours onto the ground; runs downhill.' end;
  return 'Last span laid. Flow ' || aqueduct_flow()
    || ' litres/min out of its head, not over its lip. ' || v_foot;
end $function$
